import type { Span } from './band'
import type { FlowPhase } from './band'
import { FLOW_COLORS, flowOf, GRAY } from './band'
import type { BandRow, CandidateRow, PaneItem, PaneMilestone, PaneState } from './reader'
import { PILL_TEXT } from './track'

// The cairn pane's lines (M205), as a plain description that register.tsx
// draws. For each active milestone: its phase, id, and title, with the
// band's percent for the row at the end of the line when its file reads
// (M208), its goal, its tasks and criteria with their boxes, and its
// newest work-log lines.
// Below them: the command that scripts/cairn_next.py recommends, the
// workable planned milestones, and the planned ones that wait on
// dependencies. With no active milestone, the ROADMAP's candidate rows
// follow, each a priority mark and its short title (M207).
// A line's `lead` and `tail` keep their width. Its `text` is cut to one
// line with an ellipsis, but for the goal's lines, which wrap: the operator
// picked one line per item at the M205 live look, so a long task list fits
// on one screen.
// The operator picked the look at the M208 prototypes: a blank row, a
// `▎`, and a gray uppercase label for each section heading, eight squares
// beside the Tasks and Criteria counts, the Next command in a pill, and the
// percent alone on the head line, with no track. At the live look the
// operator asked for the phase colors: a milestone's marks and meters take
// its phase's color, the queue's take plan's, and the pill takes the color
// of the phase its command runs. The colors are theme keys (M217).
// While no cairn skill runs, the Next line also carries the band's
// next-step label after the pill, which register.tsx draws as a Button
// (M218). After that Button the line carries Status, and Clear before it
// while `ended` is true, which register.tsx draws as Buttons (M219).

// The Next line's `action`, when set, is the label of the next-step Button
// drawn after its tail. No other line carries one: register.tsx draws it
// with the one key `cairn-pane-next` and the next-step press.
// The Next line's `buttons` name the Buttons that register.tsx draws after
// its action Button, in order (M219). No other line carries them.
export type PaneButton = 'clear' | 'status'
export type PaneLine = {
  key: string
  indent: number
  lead: Span[]
  text: Span | null
  tail?: Span[]
  wraps?: true
  action?: string
  buttons?: PaneButton[]
}

// The next-step Button's label by the action that scripts/cairn_next.py
// names (M212), planning among them (M213). The band and the pane read
// this one map (M218).
export const PLAN_LABEL = 'Plan'
export const NEXT_LABELS: Record<string, string> = {
  review: 'Review',
  resume: 'Resume',
  implement: 'Implement',
  'plan the next milestone': PLAN_LABEL,
}

// The actions whose next-step Button runs `/clear` first and its command in
// the cleared conversation (M221): `Implement` and `Plan`. A resumed run
// and a review keep their conversation. Each is a key of `NEXT_LABELS`.
export const CLEARS_FIRST: readonly string[] = ['implement', 'plan the next milestone']

// An action's label, read from the map's own keys only, so an action named
// like an object property, such as `toString`, has none (M218 review).
export function nextLabel(action: string): string | undefined {
  return Object.prototype.hasOwnProperty.call(NEXT_LABELS, action) ? NEXT_LABELS[action] : undefined
}

// The Status and Clear Buttons' labels (M212, M216). The band and the
// pane's Next line read these (M219).
export const STATUS_LABEL = 'Status'
export const CLEAR_LABEL = 'Clear'

export const NO_ROADMAP = 'no cairn ROADMAP found'
export const NO_FILE = 'no milestone file'
export const NO_ACTIVE = 'no active milestone'
export const CHECKED_MARK = '✓'
export const OPEN_MARK = '○'
// A candidate row's mark for each priority (M207).
export const PRIORITY_MARK: Record<CandidateRow['priority'], Span> = {
  high: { text: '↑', color: FLOW_COLORS.implement, bold: true },
  normal: { text: '·' },
  low: { text: '↓', color: GRAY },
}
// A section heading's accent mark, in the phase's color (M208).
export const ACCENT_MARK = '▎'
// The meter's squares, filled and empty, and how many it draws (M208).
export const METER_FULL = '■'
export const METER_EMPTY = '□'
export const METER_CELLS = 8
// The empty squares' theme key, as the band's terminal track marks use (M208 review).
export const METER_EMPTY_KEY = 'subtle'
// The warning text's theme key, as the band's warning labels use.
const WARNING = 'warning'

const PHASE: Record<string, { label: string; color: string }> = {
  'in-progress': { label: 'implement', color: FLOW_COLORS.implement },
  review: { label: 'review', color: FLOW_COLORS.review },
}
// The phase each recommended command runs, for the Next pill's color.
export const COMMAND_PHASE: Record<string, FlowPhase> = {
  '/milestone-plan': 'plan',
  '/milestone-implement': 'implement',
  '/milestone-review': 'review',
}
// The queue's headings are about planned work and candidates.
const QUEUE_COLOR = FLOW_COLORS.plan

const line = (key: string, indent: number, lead: Span[], text: Span | null = null): PaneLine => ({
  key,
  indent,
  lead,
  text,
})

// One blank row, before each section heading, each milestone after the
// first, and Next.
const gap = (key: string) => line(key, 0, [], { text: ' ' })

// The filled share of the meter: none only with no box checked, and all
// only with every box checked.
export function meterFill(checked: number, total: number): number {
  if (total === 0 || checked === 0) return 0
  if (checked >= total) return METER_CELLS
  return Math.min(METER_CELLS - 1, Math.max(1, Math.round((METER_CELLS * checked) / total)))
}

export function meter(checked: number, total: number, color: string): Span[] {
  const fill = meterFill(checked, total)
  return [
    { text: METER_FULL.repeat(fill), color },
    { text: METER_EMPTY.repeat(METER_CELLS - fill), color: METER_EMPTY_KEY },
  ].filter(span => span.text !== '')
}

// A section heading and the blank row before it: the accent in `color`,
// the label in gray uppercase, and its count and meter where it has them.
function heading(key: string, label: string, color: string, after: Span[] = []): PaneLine[] {
  return [
    gap(`${key}-gap`),
    line(key, 0, [
      { text: ACCENT_MARK, color },
      { text: ' ' },
      { text: label.toUpperCase(), color: GRAY, bold: true },
      ...after,
    ]),
  ]
}

function counted(key: string, label: string, list: PaneItem[], color: string): PaneLine[] {
  const checked = list.filter(item => item.checked).length
  return heading(key, label, color, [
    { text: ' ' },
    { text: `${checked}/${list.length}`, color: GRAY },
    { text: ' ' },
    ...meter(checked, list.length, color),
  ])
}

function items(prefix: string, list: PaneItem[]): PaneLine[] {
  return list.map((item, i) =>
    line(
      `${prefix}-${i}`,
      2,
      [item.checked ? { text: CHECKED_MARK, color: GRAY } : { text: OPEN_MARK }, { text: ' ' }],
      item.checked ? { text: item.text, color: GRAY } : { text: item.text },
    ),
  )
}

function milestoneLines(row: PaneMilestone, band: BandRow | undefined): PaneLine[] {
  const phase = PHASE[row.status] ?? { label: row.status, color: GRAY }
  const head = line(
    `${row.id}-head`,
    0,
    [{ text: phase.label, color: phase.color, bold: true }, { text: ' ' }, { text: row.id, bold: true }, { text: '  ' }],
    { text: row.title },
  )
  const file = row.file
  // The band's percent for the row, from its own counts, which count a box
  // inside an HTML comment where the pane's items do not.
  const flow = file === null || band === undefined ? null : flowOf(band)
  if (flow !== null && flow.percent !== null) head.tail = [{ text: '  ' }, { text: `${flow.percent}%`, color: GRAY }]
  const out: PaneLine[] = [head]
  if (file === null) return [...out, line(`${row.id}-nofile`, 2, [], { text: NO_FILE, color: WARNING })]
  if (file.goal !== '') {
    out.push(...heading(`${row.id}-goal-head`, 'Goal', phase.color))
    // A blank line between paragraphs draws as one space, so it keeps its row.
    file.goal.split('\n').forEach((text, i) =>
      out.push({ ...line(`${row.id}-goal-${i}`, 2, [], { text: text === '' ? ' ' : text }), wraps: true }),
    )
  }
  if (file.tasks.length > 0) {
    out.push(...counted(`${row.id}-tasks-head`, 'Tasks', file.tasks, phase.color))
    out.push(...items(`${row.id}-task`, file.tasks))
  }
  if (file.criteria.length > 0) {
    out.push(...counted(`${row.id}-criteria-head`, 'Criteria', file.criteria, phase.color))
    out.push(...items(`${row.id}-criterion`, file.criteria))
  }
  if (file.log.length > 0) {
    out.push(...heading(`${row.id}-log-head`, 'Work log', phase.color))
    file.log.forEach((text, i) => out.push(line(`${row.id}-log-${i}`, 2, [], { text, color: GRAY })))
  }
  return out
}

// The pane's lines from its state and the band's rows, whose counts give
// each head line its percent. `acts` is true while no cairn skill's step is
// set, and then the Next line carries its action label (M218) and the
// Status Button after it (M219). `ended` is true from a
// Stop that ends a cairn skill's step until the next idle typed prompt,
// cairn skill prompt, or session end, and then the Clear Button comes
// before Status (M219).
export function paneLines(state: PaneState, band: BandRow[] = [], acts = false, ended = false): PaneLine[] {
  if (!state.found) return [line('no-roadmap', 0, [], { text: NO_ROADMAP, color: GRAY })]
  const out: PaneLine[] = []
  if (state.milestones.length === 0) out.push(line('no-active', 0, [], { text: NO_ACTIVE, color: GRAY }))
  state.milestones.forEach((row, i) => {
    if (i > 0) out.push(gap(`${row.id}-gap`))
    out.push(...milestoneLines(row, band.find(b => b.id === row.id && b.status === row.status)))
  })
  if (state.next !== null) {
    const target = state.next.id === null ? state.next.command : `${state.next.command} ${state.next.id}`
    out.push(gap('next-gap'))
    const next = line('next', 0, [{ text: 'Next', bold: true }, { text: '  ' }], {
      text: ` ${target} `,
      color: PILL_TEXT,
      backgroundColor: FLOW_COLORS[COMMAND_PHASE[state.next.command] ?? 'implement'],
      // Bold, as the band's pill is. The text and fill are the theme's own
      // keys (M217), so their contrast is the theme's.
      bold: true,
    })
    const label = nextLabel(state.next.action)
    // Status and Clear follow the next-step Button and show only with it, as
    // the band's show only with a next-step label (M219 review).
    if (acts && label !== undefined) {
      next.action = label
      next.buttons = ended ? ['clear', 'status'] : ['status']
    }
    out.push(next)
  }
  if (state.workable.length > 0) {
    out.push(...heading('workable-head', 'Workable', QUEUE_COLOR))
    for (const row of state.workable) {
      out.push(line(`workable-${row.id}`, 2, [{ text: row.id, bold: true }, { text: '  ' }], { text: row.title }))
    }
  }
  if (state.waiting.length > 0) {
    out.push(...heading('waiting-head', 'Waiting', QUEUE_COLOR))
    for (const row of state.waiting) {
      out.push(
        line(`waiting-${row.id}`, 2, [{ text: row.id, bold: true }, { text: '  ' }], {
          text: `${row.title} · on ${row.unmet.join(', ')}`,
        }),
      )
    }
  }
  // With no active milestone, the ROADMAP's candidate rows (M207).
  if (state.milestones.length === 0 && state.candidates.length > 0) {
    out.push(
      ...heading('candidates-head', 'Candidates', QUEUE_COLOR, [{ text: ' ' }, { text: `${state.candidates.length}`, color: GRAY }]),
    )
    state.candidates.forEach((row, i) =>
      out.push(
        line(
          `candidate-${i}`,
          2,
          [PRIORITY_MARK[row.priority], { text: ' ' }],
          row.priority === 'low' ? { text: row.title, color: GRAY } : { text: row.title },
        ),
      ),
    )
  }
  return out
}

files.hooks/status/reader.ts:
// The status band's reader: which milestones are active, how many of their
// tasks and criteria are checked, and the first open one of each, and which
// planned milestones are workable. It mirrors the Python helpers the
// validator uses (`parse_roadmap_rows_full` in hooks/cairn_common.py, `_section_body` and
// `_AC_ITEM` in scripts/cairn_validate.py, `find_cairn_root` for the walk),
// and `workable` in scripts/cairn_next.py over the rows `cairn_scripts.rows`
// parses (its Depends-on cells through `parse_depends`), with what
// `workable` reaches through `done_ids` and `_workable` (`canon_id`,
// `archive_files`, and `sort_by_priority` with its `id_num`). For the cairn
// pane it also mirrors `recommend` and `waiting` in scripts/cairn_next.py
// (M205), and reads the candidate rows in the sections that
// `candidate_count` in scripts/cairn_scripts.py walks (M207). The mirror reads ASCII digits only, where Python's `isdigit`, `isdecimal`,
// and `\d` also take other Unicode digits, so an id such as `M００５７`
// reads differently in the two.
// hooks/status/reader.test.ts holds this reader, and
// scripts/tests/test_status_fixtures.py the Python helpers, to the same
// fixtures.

// Where the reader gets files. The shipped mod reads through `$.fs` and
// `$.session`; the tests read an in-memory copy of a fixture.
export type FileSource = {
  cwd: () => Promise<string>
  isFile: (path: string) => Promise<boolean>
  // The file's text, or null when it cannot be read.
  read: (path: string) => Promise<string | null>
  // The names of a directory's entries, or null when it cannot be listed.
  list: (path: string) => Promise<string[] | null>
}

// A planned milestone whose dependencies are all done.
export type WorkableRow = { id: string; title: string }

// What the band reads: the active rows in ROADMAP order, and the workable
// planned rows by priority and then id, whether or not a row is active.
export type BandState = { rows: BandRow[]; workable: WorkableRow[] }

// The counts and next items are all null when the row's milestone path is
// not a readable regular file. A next item is also null when its section
// holds no open box.
export type BandRow = {
  id: string
  title: string
  status: string
  tasksChecked: number | null
  tasksTotal: number | null
  criteriaChecked: number | null
  criteriaTotal: number | null
  // The first open task or criterion line, less its `- [ ]` prefix.
  nextTask: string | null
  nextCriterion: string | null
}

export type Fixture = {
  cwd: string
  files: Record<string, string>
  rows: BandRow[]
  // The ordered ids of the workable planned rows, as cairn_next.py lists them.
  workable: string[]
  // The pane's milestones, and `recommend` with `waiting` beside it, as
  // scripts/tests/test_status_fixtures.py computes them; `next` is null
  // with no ROADMAP (M205).
  pane: PaneMilestone[]
  next: (NextStep & { waiting: WaitingRow[] }) | null
  // The pane's candidate rows, as test_status_fixtures.py reads them (M207).
  candidates: CandidateRow[]
  // Paths that stat as files but whose read fails in the tests.
  unreadable: string[]
}

export const ACTIVE: readonly string[] = ['in-progress', 'review']

const AC_ITEM = /^\s*-\s*\[[ xX]\]/
const CHECKED = /^\s*-\s*\[[xX]\]/
const OPEN_BOX = /^\s*-\s*\[ \]\s*/

// The line breaks Python's str.splitlines() splits on.
const LINE_BREAK = new RegExp(
  '\\r\\n|[\\n\\r\\v\\f\\x1c\\x1d\\x1e\\x85' + String.fromCharCode(0x2028, 0x2029) + ']',
)

export function splitLines(text: string): string[] {
  return text.split(LINE_BREAK)
}

export type RoadmapRow = {
  id: string
  title: string
  status: string
  depends: string
  priority: string
  relpath: string
}

export function parseRoadmapRows(text: string): RoadmapRow[] {
  const rows: RoadmapRow[] = []
  for (const line of splitLines(text)) {
    if (!line.trimStart().startsWith('|')) continue
    const cells = line.split('|').slice(1, -1).map(c => c.trim())
    if (cells.length < 6 || !cells[0].startsWith('M')) continue
    rows.push({
      id: cells[0],
      title: cells[1],
      status: cells[2].toLowerCase(),
      depends: cells[3],
      priority: cells[4],
      relpath: cells[5],
    })
  }
  return rows
}

const DIGITS = /^\d+$/

// The milestone ids in a Depends-on cell, as `parse_depends` for ASCII
// digits: a token is an `M` and digits, and every other token, `—`
// included, is dropped.
export function parseDepends(cell: string): string[] {
  return cell
    .trim()
    .split(/[,\s]+/)
    .filter(token => token.startsWith('M') && DIGITS.test(token.slice(1)))
}

// An id at three-digit padding, as `canon_id` for ASCII digits: `M57`,
// `M057`, and `M0057` are `M057`, and a non-numeric id stays as it is.
export function canonId(id: string): string {
  const rest = id.slice(1)
  return DIGITS.test(rest) ? `M${BigInt(rest).toString().padStart(3, '0')}` : id
}

// The sort key of an id: its number, or after every numeric id.
function idNumber(id: string): number {
  const rest = id.slice(1)
  return DIGITS.test(rest) ? Number(rest) : 1e9
}

// A Map, so a priority word such as `constructor` reads as normal.
const PRIORITY_RANK = new Map([
  ['high', 0],
  ['normal', 1],
  ['low', 2],
])

function priorityRank(priority: string): number {
  return PRIORITY_RANK.get(priority.toLowerCase()) ?? 1
}

// The planned rows whose Depends-on ids are each a done row or in
// `archived`, by priority and then id; the sort keeps ROADMAP order on a
// tie. `archived` holds ids at three-digit padding.
export function workableRows(rows: RoadmapRow[], archived: string[]): WorkableRow[] {
  const done = new Set([...rows.filter(row => row.status === 'done').map(row => canonId(row.id)), ...archived])
  return rows
    .filter(row => row.status === 'planned' && parseDepends(row.depends).every(dep => done.has(canonId(dep))))
    .sort((a, b) => priorityRank(a.priority) - priorityRank(b.priority) || idNumber(a.id) - idNumber(b.id))
    .map(row => ({ id: row.id, title: row.title }))
}

// The glob `M*.md` and the id at the start of each name, as `archive_files`.
const ARCHIVE_NAME = /^M[\s\S]*\.md$/
const ARCHIVE_ID = /^M\d+/

// The ids, at three-digit padding, of the archive files directly under
// cairn/milestones/archive/.
async function archivedIds(source: FileSource, root: string): Promise<string[]> {
  const names = (await source.list(join(root, 'cairn/milestones/archive'))) ?? []
  const ids: string[] = []
  for (const name of names) {
    const id = ARCHIVE_NAME.test(name) ? ARCHIVE_ID.exec(name)?.[0] : undefined
    if (id !== undefined) ids.push(canonId(id))
  }
  return ids
}

// Lines under the first `## <heading>` H2, up to the next H2 or the end.
export function sectionBody(text: string, heading: string): string[] {
  const out: string[] = []
  let inSection = false
  for (const line of splitLines(text)) {
    if (line.startsWith('## ')) {
      if (inSection) break
      inSection = line.slice(3).trim().toLowerCase().startsWith(heading.toLowerCase())
      continue
    }
    if (inSection) out.push(line)
  }
  return out
}

export type SectionFields = { checked: number; total: number; next: string | null }

// The checkbox counts of one section and its first open line, less the box.
export function sectionFields(text: string, heading: string): SectionFields {
  const items = sectionBody(text, heading).filter(line => AC_ITEM.test(line))
  const open = items.find(line => OPEN_BOX.test(line))
  return {
    checked: items.filter(line => CHECKED.test(line)).length,
    total: items.length,
    next: open === undefined ? null : open.replace(OPEN_BOX, ''),
  }
}

const NO_FILE = {
  tasksChecked: null,
  tasksTotal: null,
  criteriaChecked: null,
  criteriaTotal: null,
  nextTask: null,
  nextCriterion: null,
}

function fileFields(text: string) {
  const tasks = sectionFields(text, 'Tasks')
  const criteria = sectionFields(text, 'Acceptance criteria')
  return {
    tasksChecked: tasks.checked,
    tasksTotal: tasks.total,
    criteriaChecked: criteria.checked,
    criteriaTotal: criteria.total,
    nextTask: tasks.next,
    nextCriterion: criteria.next,
  }
}

export function dirname(path: string): string {
  const trimmed = path.length > 1 ? path.replace(/[\\/]+$/, '') : path
  // A UNC share root (`\\host\share`) is a root, as a drive is (M210).
  if (/^[\\/]{2}[^\\/]+[\\/][^\\/]+$/.test(trimmed)) return trimmed
  const cut = Math.max(trimmed.lastIndexOf('/'), trimmed.lastIndexOf('\\'))
  if (cut < 0) return trimmed
  if (cut === 0) return trimmed[0]
  const head = trimmed.slice(0, cut)
  return /^[A-Za-z]:$/.test(head) ? head + trimmed[cut] : head
}

export function join(dir: string, rel: string): string {
  return `${dir.replace(/[\\/]+$/, '')}/${rel}`
}

// The nearest directory at or above `cwd` that holds cairn/ROADMAP.md.
export async function findRoot(source: FileSource, cwd: string): Promise<string | null> {
  let path = cwd
  for (;;) {
    if (await source.isFile(join(path, 'cairn/ROADMAP.md'))) return path
    const parent = dirname(path)
    if (parent === path) return null
    path = parent
  }
}

// One row per `in-progress` or `review` milestone, in ROADMAP order, and
// the workable list. Empty when no ROADMAP is found, and null when one is
// found but cannot be read (M200) or is empty (M210). `read_roadmap` in
// scripts/cairn_scripts.py reads an unreadable ROADMAP as empty instead.
export async function loadBand(source: FileSource): Promise<BandState | null> {
  const loaded = await loadCairn(source)
  return loaded === null ? null : loaded.band
}

// The band's state and the pane's from one read of the files (M205). Null
// when a ROADMAP is found but cannot be read, or its text is empty or only
// whitespace, as a write half done can leave it (M210).
export async function loadCairn(source: FileSource): Promise<{ band: BandState; pane: PaneState } | null> {
  const root = await findRoot(source, await source.cwd())
  return root === null ? emptyCairn() : loadAt(source, root)
}

// The same read with the root it found (M210): `root` is null when no
// ROADMAP is found, and `state` is null when a found one cannot be read,
// its text is empty or only whitespace, or a throw ends the read. A throw
// from `source.cwd()` is not caught, since it leaves the root unknown.
export async function readCairn(
  source: FileSource,
): Promise<{ root: string | null; state: { band: BandState; pane: PaneState } | null }> {
  const root = await findRoot(source, await source.cwd())
  if (root === null) return { root, state: emptyCairn() }
  try {
    return { root, state: await loadAt(source, root) }
  } catch {
    return { root, state: null }
  }
}

function emptyCairn(): { band: BandState; pane: PaneState } {
  return { band: { rows: [], workable: [] }, pane: NO_PANE }
}

async function loadAt(source: FileSource, root: string): Promise<{ band: BandState; pane: PaneState } | null> {
  const roadmap = await source.read(join(root, 'cairn/ROADMAP.md'))
  if (roadmap === null || roadmap.trim() === '') return null
  const parsed = parseRoadmapRows(roadmap)
  const out: BandRow[] = []
  const milestones: PaneMilestone[] = []
  for (const row of parsed) {
    if (!ACTIVE.includes(row.status)) continue
    // A regular file only, as Python's os.path.isfile: a path to a pipe or
    // a device would otherwise stall the read at every turn end.
    const path = join(root, `cairn/${row.relpath}`)
    const text = (await source.isFile(path)) ? await source.read(path) : null
    const fields = text === null ? NO_FILE : fileFields(text)
    out.push({ id: row.id, title: row.title, status: row.status, ...fields })
    milestones.push({ id: row.id, title: row.title, status: row.status, file: text === null ? null : paneFile(text) })
  }
  const archived = await archivedIds(source, root)
  const workable = workableRows(parsed, archived)
  return {
    band: { rows: out, workable },
    pane: {
      found: true,
      milestones,
      next: recommend(parsed, workable),
      workable,
      waiting: waitingRows(parsed, archived),
      candidates: candidateRows(roadmap),
    },
  }
}

// The cairn pane's state (M205): the active milestones in full, the
// queue that scripts/cairn_next.py prints, and the candidate rows (M207).
// `found` is false when no ROADMAP is found.
export type PaneState = {
  found: boolean
  milestones: PaneMilestone[]
  next: NextStep | null
  workable: WorkableRow[]
  waiting: WaitingRow[]
  candidates: CandidateRow[]
}

// One candidate row of the ROADMAP: its priority token's level, `normal`
// with no token, and its short title.
export type CandidateRow = { priority: 'high' | 'normal' | 'low'; title: string }

export type PaneItem = { text: string; checked: boolean }

// `file` is null when the milestone file is missing or its read fails.
export type PaneMilestone = {
  id: string
  title: string
  status: string
  file: { goal: string; tasks: PaneItem[]; criteria: PaneItem[]; log: string[] } | null
}

// `recommend` in scripts/cairn_next.py: `id` is null for planning.
export type NextStep = { action: string; command: string; id: string | null }

// `waiting` in scripts/cairn_next.py: `unmet` holds each undone dependency
// as written, with its row's status or `unknown`.
export type WaitingRow = { id: string; title: string; unmet: string[] }

export const NO_PANE: PaneState = { found: false, milestones: [], next: null, workable: [], waiting: [], candidates: [] }

// How many work-log lines the pane shows, newest last.
export const LOG_LINES = 5

const COMMENT = /<!--[\s\S]*?-->/g
const ITEM_BOX = /^\s*-\s*\[[ xX]\]\s*/
const LOG_ITEM = /^- /

// A section's lines with HTML comments removed, as the template's owner
// notes are.
function sectionText(text: string, heading: string): string[] {
  return splitLines(sectionBody(text, heading).join('\n').replace(COMMENT, ''))
}

// A section's checkbox items. A non-blank indented line that is not itself
// an item continues the item above it, so a wrapped task reads whole.
export function sectionItems(text: string, heading: string): PaneItem[] {
  const items: PaneItem[] = []
  let current: PaneItem | null = null
  for (const line of sectionText(text, heading)) {
    if (AC_ITEM.test(line)) {
      current = { text: line.replace(ITEM_BOX, ''), checked: CHECKED.test(line) }
      items.push(current)
    } else if (current !== null && /^\s/.test(line) && line.trim() !== '') {
      current.text = `${current.text} ${line.trim()}`
    } else {
      current = null
    }
  }
  return items
}

function paneFile(text: string) {
  return {
    goal: sectionText(text, 'Goal').join('\n').trim(),
    tasks: sectionItems(text, 'Tasks'),
    criteria: sectionItems(text, 'Acceptance criteria'),
    log: sectionText(text, 'Work log')
      .filter(line => LOG_ITEM.test(line))
      .slice(-LOG_LINES)
      .map(line => line.replace(LOG_ITEM, '')),
  }
}

const PRIORITY_TOKENS: readonly [string, 'high' | 'low'][] = [
  ['[high] ', 'high'],
  ['[low] ', 'low'],
]

// The candidate rows (M207): each flush-left line that opens with `- `
// under a `## Candidates` heading. HTML comments are removed from each such
// section's body before it is read, so the `/cairn-init` skeleton's
// placeholder rows are not read, and a `<!--` in another section hides
// nothing here. Every `## ` line starts or ends a section, as in
// `candidate_count` in scripts/cairn_scripts.py, which also counts indented
// lines and lines inside comments. A row's priority is `high` or `low` when
// its text opens with exactly `[high] ` or `[low] `, else `normal`. Its
// short title is the text after that token up to the first `: `, or all of it.
export function candidateRows(roadmap: string): CandidateRow[] {
  const bodies: string[][] = []
  let body: string[] | null = null
  for (const line of splitLines(roadmap)) {
    if (line.startsWith('## ')) {
      body = line.trim().toLowerCase().startsWith('## candidates') ? [] : null
      if (body !== null) bodies.push(body)
      continue
    }
    if (body !== null) body.push(line)
  }
  const rows: CandidateRow[] = []
  for (const line of bodies.flatMap(lines => splitLines(lines.join('\n').replace(COMMENT, '')))) {
    if (!line.startsWith('- ')) continue
    let text = line.slice(2)
    let priority: CandidateRow['priority'] = 'normal'
    const match = PRIORITY_TOKENS.find(([token]) => text.startsWith(token))
    if (match !== undefined) {
      priority = match[1]
      text = text.slice(match[0].length)
    }
    const cut = text.indexOf(': ')
    rows.push({ priority, title: (cut < 0 ? text : text.slice(0, cut)).trim() })
  }
  return rows
}

// `recommend` in scripts/cairn_next.py, over the rows and the workable list.
export function recommend(rows: RoadmapRow[], workable: WorkableRow[]): NextStep {
  const review = rows.find(row => row.status === 'review')
  if (review !== undefined) return { action: 'review', command: '/milestone-review', id: review.id }
  const active = rows.find(row => row.status === 'in-progress')
  if (active !== undefined) return { action: 'resume', command: '/milestone-implement', id: active.id }
  if (workable.length > 0) return { action: 'implement', command: '/milestone-implement', id: workable[0].id }
  return { action: 'plan the next milestone', command: '/milestone-plan', id: null }
}

// `waiting` in scripts/cairn_next.py: the planned rows with a dependency
// not yet done, in ROADMAP order. A later row with the same id wins the
// status lookup, as the Python dict does.
export function waitingRows(rows: RoadmapRow[], archived: string[]): WaitingRow[] {
  const done = new Set([...rows.filter(row => row.status === 'done').map(row => canonId(row.id)), ...archived])
  const byId = new Map<string, RoadmapRow>()
  for (const row of rows) byId.set(canonId(row.id), row)
  const out: WaitingRow[] = []
  for (const row of rows) {
    if (row.status !== 'planned') continue
    const unmet = parseDepends(row.depends)
      .filter(dep => !done.has(canonId(dep)))
      .map(dep => `${dep} (${byId.get(canonId(dep))?.status ?? 'unknown'})`)
    if (unmet.length > 0) out.push({ id: row.id, title: row.title, unmet })
  }
  return out
}

// The names directly under `dir` in a set of absolute file paths: a file's
// name, or the first part of a deeper path. Null when nothing is under it.
export function listNames(paths: string[], dir: string): string[] | null {
  const prefix = `${dir.replace(/[\\/]+$/, '')}/`
  const names = new Set<string>()
  for (const path of paths) if (path.startsWith(prefix)) names.add(path.slice(prefix.length).split('/')[0])
  return names.size === 0 ? null : [...names]
}

// An in-memory file source over absolute paths, for the tests. A path in
// `unreadable` stats as a file, and its read fails.
export function memorySource(files: Record<string, string>, cwd: string, unreadable: string[] = []): FileSource {
  return {
    cwd: async () => cwd,
    isFile: async path => Object.prototype.hasOwnProperty.call(files, path),
    read: async path =>
      Object.prototype.hasOwnProperty.call(files, path) && !unreadable.includes(path) ? files[path] : null,
    list: async dir => listNames(Object.keys(files), dir),
  }
}

