    ],
    "PostToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"${CLAUDE_PLUGIN_ROOT}/hooks/merge_guard_post.py\" || py -3 \"${CLAUDE_PLUGIN_ROOT}/hooks/merge_guard_post.py\"",
            "timeout": 15
          }
        ]
      }
    ],
    "PostToolUseFailure": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"${CLAUDE_PLUGIN_ROOT}/hooks/merge_guard_post.py\" || py -3 \"${CLAUDE_PLUGIN_ROOT}/hooks/merge_guard_post.py\"",
            "timeout": 15
          }
        ]
      }
    ]
  }
}

